// Starter
struct Student {
    let name: String
    var grade: Int   // 0...100
}

// Your task:
// Add a method `incrementGrade(by:)` that increases `grade` by the given amount,
// clamped to a maximum of 100. Then write the two lines that mutate `alice` and print her grade.
